using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Integration.Aspire;
using Microsoft.Extensions.AI;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static async Task Initialize(TestContext context)
    {
        s_reportingConfiguration =
            await AspireEvaluationReportingConfiguration.CreateAsync(
                chatClientResourceName: "chat",
                appHostAssembly: typeof(Program).Assembly,
                evaluators:
                [
                    new CoherenceEvaluator(),
                    new RelevanceEvaluator(),
                    new FluencyEvaluator(),
                ]);
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(GreetingResponse_IsCoherentAndRelevant));

        var chatClient = scenario.ChatClient!;

        var response = await chatClient.GetResponseAsync("Say hello and introduce yourself briefly.");

        scenario.Record(
            new ChatMessage(ChatRole.User, "Say hello and introduce yourself briefly."),
            response);

        await scenario.EvaluateAsync();
    }

    [TestMethod]
    public async Task FactualQuestion_IsRelevantAndFluent()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(FactualQuestion_IsRelevantAndFluent));

        var chatClient = scenario.ChatClient!;

        var response = await chatClient.GetResponseAsync("What is the capital of France?");

        scenario.Record(
            new ChatMessage(ChatRole.User, "What is the capital of France?"),
            response);

        await scenario.EvaluateAsync();
    }
}

